use serde_json::Value;
mod existing { use serde_json::Value; #[derive(PartialEq,Eq)] pub enum Scope {Full,Entry}
pub(super) fn archive_passes(scope: Scope, report: &Value) -> bool {
    scope == Scope::Full
        && report["native_frames"].as_u64().is_some_and(|frames|
            frames > 0 && report["replayed_frames"].as_u64() == Some(frames))
        && report["mismatches"].as_array().is_some_and(Vec::is_empty)
        && report["errors"].as_array().is_some_and(Vec::is_empty)
}
}
fn main(){let report:Value=serde_json::from_reader(std::fs::File::open(std::env::args().nth(1).unwrap()).unwrap()).unwrap(); assert!(existing::archive_passes(existing::Scope::Full,&report));assert!(!existing::archive_passes(existing::Scope::Entry,&report)); for key in ["errors","mismatches"] {let mut wrong=report.clone();wrong[key]=serde_json::json!([{}]);assert!(!existing::archive_passes(existing::Scope::Full,&wrong));} let mut partial=report.clone();partial["replayed_frames"]=serde_json::json!(0);assert!(!existing::archive_passes(existing::Scope::Full,&partial));println!("pinned existing acceptance code accepts the retained complete comparison counts; partial, diagnostic, error and mismatch cases rejected");}
